        beatSystemCopy: {
            saveTheCatTitle: 'Save the Cat',
            saveTheCatDesc: 'Betont klare emotionale Beats und die Bindung des Publikums.\n\nVerwenden Sie es, wenn Sie klare Wendepunkte, sichtbare Umschwünge und einen starken, publikumsorientierten Schwung vom Aufbau bis zum Finale wollen.\n\nIdeal für: Unterhaltungsliteratur, Drehbücher, High-Concept-Genres\nDynamikprofil: Aufbau -> Wende in der Mitte -> abschließende Auflösung',
            saveTheCatExamples: 'Beispiele: Die Tribute von Panem, Der Marsianer, Das Schicksal ist ein mieser Verräter.',
            saveTheCatSourceLabel: 'Jessica Brodys Save-the-Cat-Bücher',
            herosJourneyTitle: 'Heldenreise',
            herosJourneyDesc: 'Verfolgt Aufbruch, Wandlung, Prüfung und Rückkehr.\n\nVerwenden Sie es, wenn Sie einen mythischen oder identitätsgetriebenen Bogen mit sichtbarer innerer und äußerer Wandlung wollen.\n\nIdeal für: Quest-Geschichten, Spekulative Fiktion, Coming-of-Age, Wandlungsreisen\nDynamikprofil: Aufbruch -> Prüfungen -> Entscheidende Prüfung -> Rückkehr mit Veränderung',
            herosJourneyExamples: 'Beispiele: Star Wars, Der Hobbit, Der Magier der Erdsee.',
            herosJourneySourceLabel: 'Christopher Voglers „The Writer\'s Journey“',
            classicDramaticTitle: 'Klassische dramatische Struktur',
            classicDramaticDesc: 'Betont Druck in Szenen, Wendepunkte, entscheidende Entscheidungen und folgenreiche Ergebnisse.\n\nVerwenden Sie es, wenn Sie prüfen möchten, ob jede Szene durch Konflikt und Veränderung Bewegung erzeugt.\n\nIdeal für: literarische Fiktion, Drama, straff lektorierte Szenenarbeit, Überarbeitungsdurchgänge\nDynamikprofil: Aufbau → Komplikation → Druck → entscheidende Wahl → Ergebnis',
            classicDramaticExamples: 'Beispiele: Stolz und Vorurteil, Hamlet, Der Pate.',
            podcastArcTitle: 'Podcast-Erzählbogen',
            podcastArcDesc: 'Gestaltet gesprochenes Erzählen rund um Hook, Aufbau, Entwicklung und Auflösung.\n\nVerwenden Sie es, wenn Sie Zuhörer stark binden und eine klare sprachliche Abfolge wollen.\n\nIdeal für: Podcasts, Audio-Essays, Monologe, gesprochenes Sachbuch\nDynamikprofil: Hook -> Rahmung -> Entwicklung -> Auflösung',
            podcastArcExamples: 'Beispiele: erzählende Podcast-Folgen, interviewbasierte Story-Folgen, dokumentarische Audiosegmente.',
            youtubeExplainerTitle: 'YouTube-Erklärbogen',
            youtubeExplainerDesc: 'Ordnet Lehren und Erklären rund um Neugier, Klarheit und Fortschritt.\n\nVerwenden Sie es, wenn Zuschauer etwas schnell verstehen und dabei aufmerksam bleiben sollen.\n\nIdeal für: Erklärvideos, Lernvideos, Kommentare, Tutorials\nDynamikprofil: Hook -> Versprechen -> Aufschlüsselung -> Erkenntnis',
            youtubeExplainerExamples: 'Beispiele: Erklärvideos, Kommentarkanäle, tutorialbasiertes Erzählen.',
            documentaryArcTitle: 'Dokumentarischer Erzählbogen',
            documentaryArcDesc: 'Bringt Chronologie, Kontext, Einsatz und Folgen in nacherzählten Ereignissen ins Gleichgewicht.\n\nVerwenden Sie es, wenn Sie das Publikum durch reale Ereignisse führen müssen, ohne an Schwung zu verlieren.\n\nIdeal für: Geschichtsschreibung, dokumentarische Struktur, Sachbuch-Erzählen, Zeitleisten\nDynamikprofil: Kontext -> Aufbau -> Wendepunkt -> Folgen',
            documentaryArcExamples: 'Beispiele: historische Dokumentationen, erzählende Geschichtskapitel, Rekonstruktionen von Ereignissen.',
            romanceLadderTitle: 'Romance-Tropen-Leiter',
            romanceLadderDesc: 'Verfolgt Anziehung, Spannung, Verletzlichkeit, Bruch und emotionale Auflösung.\n\nVerwenden Sie es, wenn der emotionale Beziehungsbogen der Hauptmotor für die Anteilnahme der Leser ist.\n\nIdeal für: Liebesromane, romantische Nebenhandlungen, Durchgänge zur Figurenchemie\nDynamikprofil: Funke -> Spannung -> Verletzlichkeit -> Bruch -> Vereinigung/Entscheidung',
            romanceLadderExamples: 'Beispiele: Enemies to Lovers, Forced Proximity, Slow Burn.',
            thrillerLadderTitle: 'Thriller-Eskalationsleiter',
            thrillerLadderDesc: 'Baut Druck durch Gefahr, Enthüllung, Umschwünge und schwindende Optionen auf.\n\nVerwenden Sie es, wenn jede Phase das Risiko verschärfen und die sicheren Entscheidungen der Hauptfigur verringern soll.\n\nIdeal für: Thriller, Spannungsromane, Verfolgungsplots, Überlebensgeschichten\nDynamikprofil: Bedrohung -> Verfolgung -> Umschwung -> Verdichtung -> Konfrontation',
            thrillerLadderExamples: 'Beispiele: Auf der Flucht, Gone Girl, Das Schweigen der Lämmer.',
            customTitle: 'Eigenes System',
            customDesc: 'Entwerfen Sie Ihr eigenes Strukturmodell für dieses Manuskript. Definieren Sie die Beats, die für Ihre Geschichte zählen — ob sie einem klassischen Bogen folgen oder einen genrespezifischen Verlauf abbilden.\n\nEigene Systeme können Tropen, thematische Wendungen, Ermittlungsmeilensteine, historische Phasen oder jeden strukturellen Rhythmus abbilden, den Sie messen möchten.',
            customExamples: 'Beispiele: eigene Roman-Workflows, maßgeschneiderte Überarbeitungssysteme, Strukturen für den Unterricht.',
            blankCustomTitle: 'Leeres eigenes System',
            blankCustomDesc: 'Beginnt leer, damit Sie Ihre eigene Struktur von Grund auf entwerfen können.\n\nVerwenden Sie es, wenn keine der Linsen aus der Bibliothek zu Ihrem Arbeitsprozess passt oder Sie ein projektspezifisches Modell möchten.\n\nIdeal für: eigenes Beat-Design, Experimente, hybride Strukturen, das Vermitteln Ihrer eigenen Methode\nDynamikprofil: vom Autor definiert',
            blankCustomExamples: 'Beginnen Sie mit mindestens 3 Beats. Benennen Sie jeden Beat nach seiner Funktion, nicht nach dem Thema. Verwenden Sie eine klare Abfolge wie Eröffnung -> Druck -> Wendung. Fügen Sie Beats nur hinzu oder ordnen Sie sie um, wenn jeder einem eigenen strukturellen Zweck dient.',
        },
