            glossaryEvenOddDef: 'Druckkonvention: GERADE Seitenzahlen (2, 4, 6 …) stehen auf der LINKEN Seite (Verso) einer aufgeschlagenen Doppelseite; UNGERADE (1, 3, 5 …) auf der RECHTEN (Recto). Seite 1 ist immer Recto. Fahren Sie mit der Maus über eine Eckenkarte, um zu sehen, zu welcher Seite sie gehört.',
