            aiModelSystemDescription: 'KI-Modelle werden auf ein neues System migriert. Es ist keine Aktion erforderlich. Details finden Sie unter Einstellungen → KI; passen Sie die Einstellungen dort an Ihre persönlichen Vorlieben an.',
            yamlStructureTitle: 'YAML-Struktur aktualisiert',
            yamlStructureDescription: 'Basis- und Eigenschafts-YAML-Sets sind jetzt sauber getrennt. Das Basis-Set definiert die Kernfelder; das Eigenschaften-Set fügt optionale Felder hinzu. Befehle und der Book Designer führen diese jetzt automatisch zusammen. Ihre Feld-Sets wurden auf die neueste Struktur aktualisiert.',
            revisionToIterationTitle: 'Aktualisierung eines YAML-Felds erforderlich',
            revisionToIterationDescription: 'Das Feld „Revision“ wurde in „Iteration“ umbenannt. Aktualisieren Sie Ihre YAML-Eigenschaften. Vorhandene Notizen mit „Revision:“ funktionieren weiterhin.',
            revisionToIterationTooltip: 'Das YAML-Feld „Revision“ wird in „Iteration“ umbenannt, um Verwechslungen zu vermeiden und die Stabilität der Codebasis zu verbessern.',
            pendingEditsTypeTitle: 'YAML-Typänderung: Pending Edits & Summary Update',
            pendingEditsTypeDescription: '„Pending Edits“ ist kein Boolean mehr. Es ist jetzt ein String, sodass es sowohl als Ja/Nein-Flag dient als auch den letzten KI-API-Aufruf (Zeitstempel und verwendete KI) festhält. Das YAML-Feld „Summary Update“ (früher „Synopsis Update“) funktioniert genauso: String-Wert mit Zeitstempel und verwendeter KI.',
            newFolderTitle: 'Neuer Radial Timeline-Ordner',
            newFolderDescription: 'In Ihrem Obsidian-Vault wurde ein neuer Radial Timeline-Ordner erstellt, um Dateien in der aktualisierten Struktur zu organisieren, darunter KI-API-Logs, Inquiry-Briefs, Social-APR-Exporte und -Kampagnen sowie weitere zugehörige Dateien.',
            logFoldersTitle: 'Log-Ordner neu organisiert',
            logFoldersDescription: 'Logs liegen jetzt unter Radial Timeline/Logs mit eigenen Ordnern für Inquiry, Gossamer, Pulse, Moves, Snapshots und Gossamer Archive. Vollständige KI-Inhaltslogs werden in Content-Unterordnern der jeweiligen Funktion gespeichert.',
            recoveryFilesTitle: 'Wiederherstellungsdateien aus Logs verschoben',
            recoveryFilesDescription: 'Snapshots und das Gossamer Archive — die Dateien, mit denen gelöschte oder überschriebene Notizdaten wiederhergestellt werden — liegen jetzt unter Radial Timeline/Recover statt unter Radial Timeline/Logs. Der Logs-Ordner enthält nur noch entbehrliche Ausführungslogs, sodass Sie ihn jederzeit leeren können, ohne Wiederherstellungsdaten zu verlieren. Falls aus der Zeit vor diesem Update noch ein Ordner unter Radial Timeline/Logs/Snapshots oder Radial Timeline/Logs/Gossamer Archive existiert, verschieben Sie genau diesen Ordner nach Radial Timeline/Recover, um die älteren Wiederherstellungsdaten zu erhalten. Warnung: Verschieben Sie NICHT Radial Timeline/Snapshots — das ist ein anderer, aktuell genutzter Ordner, aus dem Timeline Repair liest, um Ihre Timeline wiederherzustellen; ein Verschieben würde diese Wiederherstellungsfunktion beschädigen.',
            inquiryProButtonsTitle: 'Inquiry-Pro-Schaltflächen neu gestaltet',
            inquiryProButtonsDescription: 'In der Inquiry-Ansicht sind von Pro erzeugte Fragen jetzt an einer magentafarbenen Nummer statt an einem inneren Ring zu erkennen. Der Punktkreis allein zeigt den Ausführungsstatus (bereit, ausgeführt, veraltet), sodass jede Schaltfläche auf einen Blick leichter zu lesen ist. Rein kosmetisch — keine Aktion erforderlich.',
            templateHotfixTitle: 'PDF-Vorlagen und Buchseiten-Beispiele aktualisiert',
